parameters.functionCode:
const { county_id, sector, files, metadata } = $input.first().json;

if (!county_id || !sector || !files) {
  throw new Error('Missing required fields: county_id, sector, files');
}

const validSectors = ['tourism', 'trade', 'education', 'agriculture', 'transport', 'health', 'culture'];
if (!validSectors.includes(sector)) {
  throw new Error(`Invalid sector: ${sector}. Must be one of: ${validSectors.join(', ')}`);
}

return {
  county_id,
  sector,
  files,
  metadata,
  status: 'classified',
  timestamp: new Date().toISOString()
};

const data = $input.first().json;
const imageFiles = data.files.filter(f => f.type.startsWith('image/'));

if (imageFiles.length === 0) return;

return imageFiles.map(f => ({
  url: f.url,
  county_id: data.county_id,
  sector: data.sector,
  type: 'image',
  metadata: f.metadata || {}
}));

